# 0017_ticket_ticketmessage's tickets_number_seq.
CREATE_NUMBER_SEQ = "create sequence if not exists oms.dispatch_batches_number_seq;"
OWN_NUMBER_SEQ = "alter sequence oms.dispatch_batches_number_seq owned by oms.dispatch_batches.number;"

ENABLE_BATCH_RLS = organization_scoped_policy_sql("oms", "dispatch_batches")
DISABLE_BATCH_RLS = 'alter table "oms"."dispatch_batches" disable row level security;'
