def file_existing_documents(apps, schema_editor):
    """Every document saved before batches existed gets one: documents
    for the same store and the same orders (an airway bill and the load
    sheet printed for it) share a batch, oldest first so batch numbers
    follow print order. Same matching rule as batch_services.
    find_or_create_batch."""
    PrintBatch = apps.get_model("oms", "PrintBatch")
    DispatchBatch = apps.get_model("oms", "DispatchBatch")
    DispatchBatchOrder = apps.get_model("oms", "DispatchBatchOrder")
    Order = apps.get_model("oms", "Order")

    by_orders = {}
    for doc in PrintBatch.objects.filter(batch__isnull=True).order_by("created_at"):
        numbers = sorted({str(n) for n in (doc.order_numbers or [])})
        key = (doc.organization_id, tuple(numbers))
        batch = None
        if numbers:
            batch = next(
                (b for b in by_orders.get(key, [])
                 if not b.courier or not doc.courier or b.courier == doc.courier),
                None,
            )
        if batch is None:
            batch = DispatchBatch.objects.create(
                organization_id=doc.organization_id, courier=doc.courier,
                created_by_user_id=doc.created_by_user_id,
            )
            order_ids = dict(
                Order.objects.filter(
                    organization_id=doc.organization_id, order_number__in=numbers
                ).values_list("order_number", "id")
            )
            DispatchBatchOrder.objects.bulk_create([
                DispatchBatchOrder(
                    organization_id=doc.organization_id, batch=batch,
                    order_id=order_ids.get(number), order_number=number,
                )
                for number in numbers
            ])
            DispatchBatch.objects.filter(pk=batch.pk).update(created_at=doc.created_at)
            if numbers:
                by_orders.setdefault(key, []).append(batch)
        elif doc.courier and not batch.courier:
            batch.courier = doc.courier
            DispatchBatch.objects.filter(pk=batch.pk).update(courier=doc.courier)
        # update(), not save() - save() would bump the document's own
        # updated_at, which is "when it was generated" on the Batch page.
        PrintBatch.objects.filter(pk=doc.pk).update(batch=batch)
        DispatchBatch.objects.filter(pk=batch.pk, updated_at__lt=doc.updated_at).update(
            updated_at=doc.updated_at
        )


def unfile_documents(apps, schema_editor):
    apps.get_model("oms", "PrintBatch").objects.update(batch=None)


